<?php session_start();if(!isset($_SESSION['user_id'])||!in_array($_SESSION['role'],['admin','agent'])){header('Location:../customer/login.php');exit;}require_once '../config/database.php';$id=(int)$_GET['id'];if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('INSERT INTO ticket_messages(ticket_id,sender_id,message) VALUES(?,?,?)');$q->execute([$id,$_SESSION['user_id'],trim($_POST['message'])]);$q=$pdo->prepare('UPDATE tickets SET status=? WHERE id=?');$q->execute([$_POST['status'],$id]);header('Location:ticket.php?id='.$id);exit;}$q=$pdo->prepare('SELECT t.*,u.name customer,u.phone FROM tickets t LEFT JOIN users u ON u.id=t.user_id WHERE t.id=?');$q->execute([$id]);$t=$q->fetch();$q=$pdo->prepare('SELECT m.*,u.name FROM ticket_messages m LEFT JOIN users u ON u.id=m.sender_id WHERE ticket_id=? ORDER BY m.id');$q->execute([$id]);$ms=$q->fetchAll();?><!doctype html><html><body style="font-family:Arial;background:#f4f7fb"><main style="max-width:900px;margin:auto;padding:25px"><a href="index.php">← Dashboard</a><h2><?=htmlspecialchars($t['ticket_no'])?> - <?=htmlspecialchars($t['subject'])?></h2><p>Customer: <?=htmlspecialchars($t['customer']??'-')?> | <?=htmlspecialchars($t['phone']??'-')?></p><div style="background:#e9eef5;padding:20px;height:400px;overflow:auto"><?php foreach($ms as $m):?><div style="background:white;padding:10px;margin:8px;border-radius:10px"><b><?=htmlspecialchars($m['name']??'User')?></b><br><?=nl2br(htmlspecialchars($m['message']))?></div><?php endforeach;?></div><form method="post"><textarea name="message" required rows="4" style="width:100%;margin-top:10px"></textarea><select name="status"><option>Open</option><option>Assigned</option><option>In Progress</option><option>Waiting</option><option>Resolved</option><option>Closed</option></select><button>Reply & Update</button></form></main></body></html>